import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const Signup = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    email: '',
    password: '',
    confirmPassword: '',
    first_name: '',
    last_name: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    // Validation
    if (formData.password !== formData.confirmPassword) {
      setError('Passwords do not match');
      return;
    }

    if (formData.password.length < 8) {
      setError('Password must be at least 8 characters');
      return;
    }

    setLoading(true);

    try {
      // Send data with snake_case format
      const requestData = {
        email: formData.email,
        password: formData.password,
        first_name: formData.first_name,
        last_name: formData.last_name
      };

      await axios.post('/signup', requestData);
      
      // Redirect to login after successful signup
      alert('Account created successfully! Please login.');
      navigate('/login');
    } catch (err) {
      setError(err.response?.data?.detail || 'Signup failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-container">
      {/* Left Panel */}
      <div className="auth-left-panel">
        <div>
          <div className="auth-logo">
            <div className="auth-logo-circle">C</div>
            <div className="auth-logo-text">
              <h1>ContractIQ</h1>
              <p>Full Stack Application</p>
            </div>
          </div>

          <div className="auth-content">
            <h2>Join ContractIQ</h2>
            <p>Create your account to start managing contracts efficiently.</p>

            <div className="roles-section">
              <h3>Available Roles</h3>
              <div className="role-badges">
                <span className="role-badge">Administrator</span>
                <span className="role-badge">Legal Manager</span>
                <span className="role-badge">Compliance Officer</span>
                <span className="role-badge">Contract Manager</span>
                <span className="role-badge">Department Head</span>
                <span className="role-badge">Employee</span>
              </div>
            </div>
          </div>
        </div>

        <div className="auth-footer">
          <span>🔒</span>
          <span>Your information is safe with us</span>
        </div>
      </div>

      {/* Right Panel */}
      <div className="auth-right-panel">
        <div className="auth-form-container">
          <div className="auth-form-header">
            <h2>Create Account</h2>
            <p>Fill in your details to get started</p>
          </div>

          <div className="security-badges">
            <span className="security-badge">
              <span>✓</span>
              <span>Secure</span>
            </span>
            <span className="security-badge">
              <span>✓</span>
              <span>Encrypted</span>
            </span>
            <span className="security-badge">
              <span>✓</span>
              <span>Private</span>
            </span>
          </div>

          {error && <div className="error-message">{error}</div>}

          <form className="auth-form" onSubmit={handleSubmit}>
            <div className="form-group">
              <label>First Name *</label>
              <input
                type="text"
                name="first_name"
                value={formData.first_name}
                onChange={handleChange}
                placeholder="Enter your first name"
                required
              />
            </div>

            <div className="form-group">
              <label>Last Name *</label>
              <input
                type="text"
                name="last_name"
                value={formData.last_name}
                onChange={handleChange}
                placeholder="Enter your last name"
                required
              />
            </div>

            <div className="form-group">
              <label>Email Address *</label>
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                placeholder="Enter your email"
                required
              />
            </div>

            <div className="form-group">
              <label>Password *</label>
              <input
                type="password"
                name="password"
                value={formData.password}
                onChange={handleChange}
                placeholder="Create a password"
                required
              />
              <small>Minimum 8 characters</small>
            </div>

            <div className="form-group">
              <label>Confirm Password *</label>
              <input
                type="password"
                name="confirmPassword"
                value={formData.confirmPassword}
                onChange={handleChange}
                placeholder="Confirm your password"
                required
              />
            </div>

            <button type="submit" className="submit-button" disabled={loading}>
              {loading ? 'Creating Account...' : 'Create Account →'}
            </button>
          </form>

          <div className="auth-footer-text">
            Already have an account? <a href="/login" onClick={(e) => { e.preventDefault(); navigate('/login'); }}>Sign In</a>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Signup;
